export interface PublicUser {
  id: string
  nickname: string
  color: string
}

export interface Room {
  id: string
  name: string
  createdAt: number
  /** `null` for the default rooms created at boot. */
  createdBy: string | null
}

export interface RoomSummary extends Room {
  onlineCount: number
}

export interface ChatMessage {
  id: string
  roomId: string
  author: PublicUser
  text: string
  /** Epoch milliseconds, assigned by the server. */
  sentAt: number
  /** Echo of the id generated by the sender, used to reconcile optimistic messages. */
  clientId?: string
}

export interface LoginResponse {
  token: string
  user: PublicUser
}

export interface JoinRoomResult {
  room: RoomSummary
  history: ChatMessage[]
  users: PublicUser[]
}
